create table xxcus.xxfnd_employees (
    employee_id           number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    source_type           varchar2(20 byte) default 'LOCAL' not null enable,
    fusion_person_id      number,
    fusion_person_number  varchar2(30 byte),
    user_name             varchar2(255 byte) not null enable,
    full_name             varchar2(240 byte) not null enable,
    email_address         varchar2(320 byte) not null enable,
    department_name       varchar2(240 byte),
    job_title             varchar2(240 byte),
    last_sync_date        timestamp(6),
    enabled_flag          varchar2(1 byte) default 'Y' not null enable,
    start_date_active     date default trunc(sysdate) not null enable,
    end_date_active       date,
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxfnd_employees
    add constraint xxfnd_employees_ck1
        check ( source_type in ( 'FUSION', 'LOCAL' ) ) enable;

alter table xxcus.xxfnd_employees
    add constraint xxfnd_employees_ck2
        check ( ( source_type = 'FUSION'
                  and fusion_person_id is not null )
                or ( source_type = 'LOCAL'
                     and fusion_person_id is null ) ) enable;

alter table xxcus.xxfnd_employees
    add constraint xxfnd_employees_ck3
        check ( enabled_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxfnd_employees
    add constraint xxfnd_employees_ck4 check ( user_name = upper(user_name) ) enable;

alter table xxcus.xxfnd_employees
    add constraint xxfnd_employees_pk primary key ( employee_id )
        using index enable;

alter table xxcus.xxfnd_employees add constraint xxfnd_employees_uk1 unique ( user_name )
    using index enable;

alter table xxcus.xxfnd_employees add constraint xxfnd_employees_uk2 unique ( email_address )
    using index enable;


